class Solution {
    /** 3331. Find Subtree Sizes After Changes
     * https://leetcode.com/problems/find-subtree-sizes-after-changes/
     */
public:
    vector<int> findSubtreeSizes(vector<int>& parent, string s) {
        const int N = parent.size();
        vector<vector<int>> adj(N);
        for (int i = 1; i < N; ++i) {
            adj[parent[i]].push_back(i);
        }
        vector<int> res(N, 1);
        vector<int> ct(26, -1);
        auto dfs = [&](this auto&& dfs, const int& id) -> void {
            const int cti = s[id] - 'a';
            const int ctv = ct[cti];
            if (-1 != ctv) parent[id] = ctv;
            ct[cti] = id;
            for (int j: adj[id]) {
                dfs(j);
            }
            ct[cti] = ctv;
            if (-1 != parent[id]) res[parent[id]] += res[id];
        };
        dfs(0);
        // for (auto x: parent) { cout << x << ','; } cout << endl;
        return res;
    }
};

class Solution {
    /** Time Limit Exceeded */
public:
    vector<int> findSubtreeSizes(vector<int>& parent, string s) {
        const int N = parent.size();
        vector<int> res(N);
        vector<int> ct(26, -1);
        auto dfs = [&](this auto&& dfs, const int& id) -> void {
            const int cti = s[id] - 'a';
            const int ctv = ct[cti];
            if (-1 != ctv) parent[id] = ctv;
            ct[cti] = id;
            res[id] = 1;
            for (int i = 1; i < N; ++i) {
                if (res[i]) continue;
                if (id == parent[i]) {
                    dfs(i);
                }
            }
            ct[cti] = ctv;
            if (-1 != parent[id]) res[parent[id]] += res[id];
        };
        dfs(0);
        // for (auto x: parent) { cout << x << ','; } cout << endl;
        return res;
    }
};

